# port scan plugin
yakit.AutoInitYakit()

/*
本插件定义的函数主要用于端口扫描的额外扩展

函数定义如下：
func(result *fp.MatchResult)

// 详细结构体定义与内容见模版结尾
// 这里最关键的是，如果对扫描出的结果有疑问，需要对 MatchResult 进行修改，应该直接
// 对变量.Field 进行修改。

DEMO:

handle = func(result) {
    if result.Fingerprint != nil {
        if result.Port == 80 && result.GetServiceName() == "" {
            result.Fingerprint.ServiceName = "http"
        }
    }
}

*/

handleCheck = func(target, port){
    target = str.HostPort(target, port)
    ishttps = str.IsTLSServer(target)
    if err != nil{
        return
    }
    if ishttps == true{
        url = "https://" + target
    }else{
        url = "http://" + target
    }

    vulnUri = "/solr/admin/info/system"
    url, err = str.UrlJoin(url, vulnUri)
    if err != nil{
        return
    }

    url += "?wt=json"

    resp, err = http.Get(url)

    println(url)

    if err != nil{
        println(err)
        return 
    }

    println(resp.StatusCode)

    // check response statuscode
    if resp.StatusCode!=200{
        return
    }

    // check if json decode correctly.
    body = http.GetAllBody(resp)

    println(string(body))

    jdata = json.loads(body)
    println(jdata)

    if len(jdata) == 0{
        return
    }

    // check keywords in response body.
    keywords = ["vendor", "version", "arch", "classpath", "solr"]

    for _, keyword = range(keywords){
        println(keyword)
        if str.Contains(string(body), keyword) == false{
            return
        }
    }

    // responseStatusCode == 200 && ContainAllKeyWords && isJsonData => vuln exists.
    risk.NewRisk(string(resp.Request.URL), risk.titleVerbose("apache solr未授权访问"), risk.level("high"))
}

handle = func(result /* *fp.MatchResult */) {
    if result.IsOpen() == false{
        return
    }  
    handleCheck(result.Target, result.Port)
}

